//
// buildTrack(points) -> { curve, rails }
//   - curve: closed CatmullRomCurve3 through `points`
//   - rails: THREE.Mesh whose geometry is a closed TubeGeometry along the curve
//
// cartPoseAt(curve, u) -> { position: Vector3, quaternion: Quaternion }
//   - position: curve.getPointAt(u)
//   - quaternion: orients the cart so its local -Z axis lies along the curve
//     tangent, while its local +Y ("up") is blended toward the curve's
//     curvature direction (computed with finite differences), giving natural
//     banking through turns and correct inversion through loops.

import {
  CatmullRomCurve3,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Quaternion,
  TubeGeometry,
  Vector3,
} from 'three';

/** Inline loop control points used by the demo scene. */
export const LOOP_POINTS = [
  [0, 2, 0],
  [10, 4, 2],
  [14, 10, 10],
  [6, 6, 16],
  [-4, 8, 10],
  [-8, 3, 4],
];

/**
 * Build a closed track from an array of points ([x,y,z] arrays or Vector3s).
 */
export function buildTrack(points) {
  const controls = points.map((p) =>
    Array.isArray(p) ? new Vector3(p[0], p[1], p[2]) : p.clone()
  );
  const curve = new CatmullRomCurve3(controls, true, 'catmullrom', 0.5);

  const geometry = new TubeGeometry(curve, 512, 0.18, 12, true);
  const material = new MeshStandardMaterial({
    color: 0x9fb4cc,
    metalness: 0.7,
    roughness: 0.35,
  });
  const rails = new Mesh(geometry, material);

  return { curve, rails };
}

function wrap01(u) {
  return ((u % 1) + 1) % 1;
}

const _worldUp = new Vector3(0, 1, 0);
const _xAxis = new Vector3();
const _yAxis = new Vector3();
const _zAxis = new Vector3();
const _mat = new Matrix4();

/**
 * Reference curvature (inverse meters) at which banking weight saturates.
 * Larger values -> less banking for the same turn.
 */
const BANK_REFERENCE_CURVATURE = 0.15;

/**
 * Pose of the cart at parameter u (0..1, wraps on the closed curve).
 *
 * Frame construction:
 *  1. tangent t      : curve.getTangentAt(u)
 *  2. curvature dir n: central finite difference of the tangent,
 *                      made perpendicular to t and normalized (points toward
 *                      the center of curvature; zero on straight sections)
 *  3. up             : normalize( proj(worldUp onto ⟂t) * wFlat
 *                                 + n * wBank )
 *     where wFlat = |projection| (degenerates to 0 on vertical tangents) and
 *     wBank grows with measured curvature. Both weights are continuous in u,
 *     so the resulting quaternion never flips.
 *  4. right          : cross(t, up), Gram-Schmidt, then quaternion from basis
 *                      with local -Z mapped onto t.
 */
export function cartPoseAt(curve, u) {
  const eps = 1e-3;
  const uu = wrap01(u);

  const position = curve.getPointAt(uu);

  const tangent = curve.getTangentAt(uu).normalize();
  const tPrev = curve.getTangentAt(wrap01(uu - eps)).normalize();
  const tNext = curve.getTangentAt(wrap01(uu + eps)).normalize();

  // Finite-difference derivative of the tangent ~ curvature vector.
  const curvature = new Vector3().subVectors(tNext, tPrev);
  curvature.addScaledVector(tangent, -curvature.dot(tangent));
  const curvatureLength = curvature.length();
  if (curvatureLength > 1e-12) curvature.divideScalar(curvatureLength);

  // World-up projected into the plane perpendicular to the tangent.
  const flat = _worldUp.clone().addScaledVector(tangent, -_worldUp.dot(tangent));
  const flatWeight = Math.min(flat.length(), 1); // -> 0 when tangent is vertical

  // Banking weight rises with curvature, saturating at the reference value.
  const measuredCurvature = curvatureLength / (2 * eps);
  const bankWeight = Math.min(measuredCurvature / BANK_REFERENCE_CURVATURE, 1);

  const up = flat.multiplyScalar(flatWeight);
  if (curvatureLength > 0) up.addScaledVector(curvature, bankWeight);
  if (up.lengthSq() < 1e-10) {
    // Degenerate (vertical tangent on a straight section): any stable
    // perpendicular works; fall back to a horizontal axis.
    up.set(tangent.z, 0, -tangent.x);
    if (up.lengthSq() < 1e-10) up.set(1, 0, 0);
  }
  up.normalize();

  // Orthonormal basis with -Z along the tangent.
  _zAxis.copy(tangent).multiplyScalar(-1); // local +Z points backwards
  _xAxis.crossVectors(tangent, up).normalize(); // local +X (cart's right)
  _yAxis.crossVectors(_zAxis, _xAxis).normalize(); // re-orthogonalized up

  _mat.makeBasis(_xAxis, _yAxis, _zAxis);
  const quaternion = new Quaternion().setFromRotationMatrix(_mat);

  return { position, quaternion };
}
"})
