result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/coaster.js", "content": "// Roller-coaster track builder + cart pose solver.
//
// buildTrack(points) -> { curve, rails }
//   - curve: closed CatmullRomCurve3 through `points`
//   - rails: THREE.Mesh whose geometry is a closed TubeGeometry along the curve
//
// cartPoseAt(curve, u) -> { position: Vector3, quaternion: Quaternion }
//   - position: curve.getPointAt(u)
//   - quaternion: orients the cart so its local -Z axis lies along the curve
//     tangent, with an up vector that follows a rotation-minimizing frame
//     (so the cart inverts smoothly through loops and never flips) plus a
//     bounded banking lean toward the curve's curvature direction, computed
//     via central finite differences of the tangent.

import {
  CatmullRomCurve3,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Quaternion,
  TubeGeometry,
  Vector3,
} from 'three';

/** Inline loop control points used by the demo scene. */
export const LOOP_POINTS = [
  [0, 2, 0],
  [10, 4, 2],
  [14, 10, 10],
  [6, 6, 16],
  [-4, 8, 10],
  [-8, 3, 4],
];

const FRAME_SAMPLES = 2048;
const EPS = 1e-3; // finite-difference step in u
/** Max banking lean fraction: up' = normalize(up + LEAN * wBank * nPerp). */
const LEAN = 0.5;
/** Curvature (1/length) at which the banking weight saturates. */
const BANK_REFERENCE_CURVATURE = 0.15;

/**
 * Build a closed track from an array of points ([x,y,z] arrays or Vector3s).
 */
export function buildTrack(points) {
  const controls = points.map((p) =>
    Array.isArray(p) ? new Vector3(p[0], p[1], p[2]) : p.clone()
  );
  const curve = new CatmullRomCurve3(controls, true, 'catmullrom', 0.5);

  const geometry = new TubeGeometry(curve, 512, 0.18, 12, true);
  const material = new MeshStandardMaterial({
    color: 0x9fb4cc,
    metalness: 0.7,
    roughness: 0.35,
  });
  const rails = new Mesh(geometry, material);

  return { curve, rails };
}

function wrap01(u) {
  return ((u % 1) + 1) % 1;
}

// ---------------------------------------------------------------------------
// Rotation-minimizing frame table (built lazily, one per curve).
// ---------------------------------------------------------------------------

const frameTables = new WeakMap();

/**
 * Reference "up" for starting the transport: world up projected perpendicular
 * to the tangent, with a safe fallback for vertical tangents.
 */
function initialUp(tangent) {
  const worldUp = new Vector3(0, 1, 0);
  const up = worldUp.addScaledVector(tangent, -worldUp.dot(tangent));
  if (up.lengthSq() < 1e-8) {
    up.set(tangent.z, 0, -tangent.x);
    if (up.lengthSq() < 1e-8) up.set(1, 0, 0);
  }
  return up.normalize();
}

/**
 * Sampled, closure-corrected parallel-transport frames along the closed curve.
 * Returns Float32Array of 3*(N+1) up vectors; entry N equals entry 0, so the
 * frame is seamless at u=0/u=1.
 */
function getFrameTable(curve) {
  let table = frameTables.get(curve);
  if (table) return table;

  const n = FRAME_SAMPLES;
  const tangents = [];
  const ups = [];

  const q = new Quaternion();
  const prevUp = new Vector3();
  const curUp = new Vector3();

  // Pass 1: transport frames around the whole loop.
  for (let i = 0; i <= n; i++) {
    const t = curve.getTangentAt(i === n ? 0 : i / n).normalize();
    tangents.push(t.clone());
    if (i === 0) {
      curUp.copy(initialUp(t));
    } else {
      // Rotate the previous up by the minimal rotation t[i-1] -> t[i].
      q.setFromUnitVectors(tangents[i - 1], t);
      curUp.copy(prevUp).applyQuaternion(q);
      curUp.addScaledVector(t, -curUp.dot(t)); // stay perpendicular
      if (curUp.lengthSq() < 1e-12) curUp.copy(initialUp(t));
      curUp.normalize();
    }
    ups.push(curUp.clone());
    prevUp.copy(curUp);
  }

  // Pass 2: closure correction. Transport around a closed loop accumulates a
  // holonomy twist alpha; unwind it linearly so frame[n] == frame[0].
  const t0 = tangents[0];
  const end = ups[n];
  const dot = Math.min(1, Math.max(-1, ups[0].dot(end)));
  const alpha = Math.atan2(
    new Vector3().crossVectors(end, ups[0]).dot(t0),
    dot
  );
  const corrected = [];
  for (let i = 0; i <= n; i++) {
    const up = ups[i]
      .clone()
      .applyAxisAngle(tangents[i], (-alpha * i) / n);
    up.addScaledVector(tangents[i], -up.dot(tangents[i])).normalize();
    corrected.push(up.x, up.y, up.z);
  }

  table = {
    count: n,
    us: Float32Array.from({ length: n + 1 }, (_, i) => i / n),
    ups: new Float32Array(corrected),
  };
  frameTables.set(curve, table);
  return table;
}

/** Interpolated rotation-minimizing up at parameter u (in [0,1]). */
function transportedUp(curve, u) {
  const { count, ups } = getFrameTable(curve);
  const uu = wrap01(u);
  const s = uu * count;
  const i = Math.min(Math.floor(s), count - 1);
  const f = s - i;

  const ax = ups[3 * i], ay = ups[3 * i + 1], az = ups[3 * i + 2];
  const j = i + 1;
  let bx = ups[3 * j], by = ups[3 * j + 1], bz = ups[3 * j + 2];

  // Keep the pair in the same hemisphere before blending.
  if (ax * bx + ay * by + az * bz < 0) {
    bx = -bx; by = -by; bz = -bz;
  }
  const up = new Vector3(
    ax + f * (bx - ax),
    ay + f * (by - ay),
    az + f * (bz - az)
  );
  return up.normalize();
}

// ---------------------------------------------------------------------------
// Public pose API
// ---------------------------------------------------------------------------

const _xAxis = new Vector3();
const _yAxis = new Vector3();
const _zAxis = new Vector3();
const _mat = new Matrix4();

/**
 * Pose of the cart at parameter u (wraps on the closed curve).
 *
 * The up vector is a rotation-minimizing frame vector (continuous, flip-free,
 * seamless across the closed seam) leaned toward the curve's curvature
 * direction: n = normalize(dTangent/du) via central finite differences, made
 * perpendicular to the tangent, scaled by a weight that grows with measured
 * curvature. The lean is a bounded perpendicular push, so the up direction
 * can never degenerate or flip.
 */
export function cartPoseAt(curve, u) {
  const uu = wrap01(u);

  const position = curve.getPointAt(uu);
  const tangent = curve.getTangentAt(uu).normalize();

  // Finite-difference derivative of the tangent ~ curvature vector.
  const tPrev = curve.getTangentAt(wrap01(uu - EPS)).normalize();
  const tNext = curve.getTangentAt(wrap01(uu + EPS)).normalize();
  const curvature = new Vector3().subVectors(tNext, tPrev);
  curvature.addScaledVector(tangent, -curvature.dot(tangent));
  const curvatureLength = curvature.length();
  if (curvatureLength > 1e-12) curvature.divideScalar(curvatureLength);

  // Up: transported frame + bounded banking lean toward the curvature.
  const up = transportedUp(curve, uu);
  up.addScaledVector(tangent, -up.dot(tangent)).normalize();
  if (curvatureLength > 1e-12) {
    const measuredCurvature = curvatureLength / (2 * EPS);
    const bankWeight =
      Math.min(measuredCurvature / BANK_REFERENCE_CURVATURE, 1) * LEAN;
    // Component of curvature direction perpendicular to the current up.
    curvature.addScaledVector(up, -curvature.dot(up));
    up.addScaledVector(curvature.normalize(), bankWeight).normalize();
  }

  // Orthonormal basis with the cart's local -Z along the tangent.
  _zAxis.copy(tangent).multiplyScalar(-1);
  _xAxis.crossVectors(tangent, up).normalize(); // cart's right
  _yAxis.crossVectors(_zAxis, _xAxis).normalize(); // re-orthogonalized up

  _mat.makeBasis(_xAxis, _yAxis, _zAxis);
  const quaternion = new Quaternion().setFromRotationMatrix(_mat);

  return { position, quaternion };
}
